64	      final DepositProcessingController depositProcessingController,
65	      final MinimumGenesisTimeBlockFinder minimumGenesisTimeBlockFinder,
66	      final Optional<UInt64> depositContractDeployBlock,
67	      final Eth1HeadTracker headTracker) {
68	    this.config = config;
69	    this.eth1Provider = eth1Provider;
70	    this.asyncRunner = asyncRunner;
71	    this.eth1EventsPublisher = eth1EventsPublisher;
72	    this.eth1DepositStorageChannel = eth1DepositStorageChannel;
73	    this.depositSnapshotFileLoader = depositSnapshotFileLoader;
74	    this.depositSnapshotStorageLoader = depositSnapshotStorageLoader;
75	    this.takeBestDepositSnapshot = takeBestDepositSnapshot;
76	    this.depositProcessingController = depositProcessingController;
77	    this.minimumGenesisTimeBlockFinder = minimumGenesisTimeBlockFinder;
78	    this.depositContractDeployBlock = depositContractDeployBlock;
79	    this.headTracker = headTracker;
80	  }
