82	  public void start() {
83	    loadDepositSnapshot()
84	        .thenCompose(
85	            depositSnapshotLoadingResult -> {
86	              if (depositSnapshotLoadingResult.getDepositTreeSnapshot().isEmpty()) {
87	                LOG.debug("No deposit tree snapshot loaded, processing full replay of deposits");
88	                return eth1DepositStorageChannel.replayDepositEvents();
89	              } else {
90	                final DepositTreeSnapshot depositTreeSnapshot =
91	                    depositSnapshotLoadingResult.getDepositTreeSnapshot().get();
92	                STATUS_LOG.loadedDepositSnapshot(
93	                    depositTreeSnapshot.getDepositCount(),
94	                    depositTreeSnapshot.getExecutionBlockHash());
95	                eth1EventsPublisher.onInitialDepositTreeSnapshot(depositTreeSnapshot);
96	                return SafeFuture.completedFuture(
97	                    depositSnapshotLoadingResult.getReplayDepositsResult());
98	              }
99	            })
100	        .thenCompose(
101	            replayDepositsResult -> {
102	              replayDepositsResult
103	                  .getLastProcessedDepositIndex()
